const MEDIA = /^(img\/photos|img\/stickers|audio)\//;
const SHELL = ASSETS.filter(([f]) => !MEDIA.test(f));
const MEDIA_FILES = ASSETS.filter(([f]) => MEDIA.test(f));

// The previous version's cache and its file hashes, if any.
async function previous() {
  const keys = await caches.keys();
  const name = keys.filter((k) => /^word-(buddies|wizard)-/.test(k) && k !== CACHE).pop();
  if (!name) return null;
  const cache = await caches.open(name);
  const res = await cache.match(MANIFEST);
  return { cache, hashes: res ? await res.json() : {} };
}

// Put `files` into `cache`: unchanged ones are copied from the previous cache,
// the rest are fetched `parallel` at a time (or left for later when parallel is 0).
// On a first install the browser's page cache is fine (it holds what the page just
// loaded); when updating, changed files are always checked with the server.
async function fill(cache, files, prev, parallel) {
  const mode = prev ? 'no-cache' : 'default';
  const todo = [];
  for (const [file, hash] of files) {
    if (await cache.match(file)) continue;
    if (prev && prev.hashes[file] === hash) {
      const old = await prev.cache.match(file);
      if (old) { await cache.put(file, old); continue; }
    }
    todo.push(file);
  }
  if (!parallel) return todo.length;
  let next = 0;
  const worker = async () => {
    while (next < todo.length) {
      const file = todo[next++];
      const res = await fetch(new Request(file, { cache: mode }));
      if (!res.ok) throw new Error('cannot fetch ' + file);
      await cache.put(file, res);
    }
  };
  await Promise.all(Array.from({ length: Math.min(parallel, todo.length) }, worker));
  return 0;
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const prev = await previous();
    await fill(cache, SHELL, prev, 6);
    await fill(cache, MEDIA_FILES, prev, 0); // keep whatever the previous version already had
    await cache.put(MANIFEST, new Response(JSON.stringify(Object.fromEntries(ASSETS)), { headers: { 'Content-Type': 'application/json' } }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => /^word-(buddies|wizard)-/.test(k) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// The page asks for the photos, stickers and clips once it is showing, and
// again on every open until they are all there.
let filling = null;
self.addEventListener('message', (event) => {
  if (!event.data || event.data.type !== 'precache') return;
  if (!filling) {
    filling = caches.open(CACHE)
      .then((cache) => fill(cache, MEDIA_FILES, null, 4))
      .catch(() => { /* offline or interrupted: next open carries on */ })
      .then(() => { filling = null; });
  }
  event.waitUntil(filling);
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((res) => {
        if (res.ok && res.type === 'basic') {
          const copy = res.clone();
          caches.open(CACHE).then((cache) => cache.put(req, copy));
        }
        return res;
      }).catch(() => (req.mode === 'navigate' ? caches.match('index.html') : Response.error()));
    })
  );
});
